const GRADES=[['F',0,.55,.70],['E',5,.60,.74],['E+',10,.70,.77],['D',15,.80,.80],['D+',21,.90,.82],['C',28,1.10,.85],['C+',36,1.30,.87],['B',46,1.50,.90],['B+',57,1.70,.92],['A',69,1.90,.93],['A+',82,2.15,.97],['S',96,2.25,.99],['SS',111,2.50,1]];
