 join(body){const r=this.room(String(body.code).trim());if(r.phase!=='waiting')fail('이미 시작한 방입니다.');if(r.players.length>=4)fail('방이 가득 찼습니다.');const p=this.player(body.character,body.nickname);r.players.push(p);return this.session(r,p);}
