 cleanStatuses(p,t){const expiredHard=[];for(const [type,e] of Object.entries(p.statusEffects||{}))if(e.until<=t){if(B.EFFECTS[type]?.hard)expiredHard.push(e.until);delete p.statusEffects[type];}if(expiredHard.length&&!Object.keys(p.statusEffects||{}).some(type=>B.EFFECTS[type]?.hard)){p.controlImmuneUntil=Math.max(p.controlImmuneUntil||0,...expiredHard.map(end=>end+2));p.controlStarted=null;}if((p.controlImmuneUntil||0)<=t)p.controlImmuneUntil=0;}
 queueStatusTicks(r,p,t){if(p.dead)return;for(const [type,e] of Object.entries(p.statusEffects||{})){if(!B.EFFECTS[type]?.dot)continue;while(e.nextTick<=t&&e.nextTick<=e.until){r.queue.push({id:++this.serial,at:e.nextTick,type:'dot',status:type,source:e.sourceId,target:p.id,power:e.tickPower*e.stacks,attribute:e.attribute});e.nextTick++;}}}
