  effects[type]={until:Math.max(previous?.until||0,end),power:Math.max(previous?.power||0,strength),stacks:Math.min(def.maxStacks||1,(previous?.stacks||0)+1),sourceId:!previous||newPower>=(oldPower||0)?source.id:previous.sourceId,attribute:!previous||newPower>=(oldPower||0)?attribute:previous.attribute,tickPower:Math.max(previous?.tickPower||0,tickPower),nextTick:previous?.nextTick??t+1};
  if(type==='stun'){target.busy=null;target.rest=null;}if(type==='silence'&&target.busy?.type==='np')target.busy=null;
  return true;
