  if(p.dead)return [];const own=viewer===p;
  const views=Object.entries(p.statusEffects||{}).filter(([,e])=>e.until>t).map(([type,e])=>({type,until:e.until,stacks:e.stacks,...(own?{power:e.power}:{})}));
  const marks=Object.entries(p.marks||{}).filter(([id,until])=>until>t&&(own||id===viewer.id));if(marks.length)views.unshift({type:'interference',until:Math.max(...marks.map(([,until])=>until)),stacks:marks.length});
  if((p.controlImmuneUntil||0)>t)views.push({type:'controlImmunity',until:p.controlImmuneUntil,stacks:1});if(own&&p.funnels?.until>t&&p.funnels.charges>0)views.push({type:'funnels',until:p.funnels.until,stacks:p.funnels.charges});return views;
