 searchTarget(p,enemies){if(!enemies.length)return null;const stance=B.STANCES[p.stance]||B.STANCES.normal,weights=enemies.map(e=>(B.STANCES[e.stance]||B.STANCES.normal).visibility),sum=weights.reduce((a,b)=>a+b,0);if(this.random()>=stance.find*sum/enemies.length)return null;let roll=this.random()*sum;return enemies.find((_,i)=>(roll-=weights[i])<0)||enemies.at(-1);}
 capacity(id){const item=this.items[id];return item?.weaponTypes.includes('gun')?item.magazine||Number.parseInt(item.reference?.fields?.['装填'])||0:0;}
