 add(p,id,n,metadata){const i=this.items[id];let left=n;if(!i||n<=0)return 0;const unique=i.kind==='weapon'&&i.stackLimit===1;for(const x of p.bag)if(x?.id===id&&!unique){const k=Math.min(left,i.stackLimit-x.qty);x.qty+=k;left-=k;}while(left>0){const index=p.bag.indexOf(null);if(index<0)break;const qty=Math.min(left,i.stackLimit);p.bag[index]={id,qty,...(unique?{meta:this.meta(id,metadata)}:{})};left-=qty;}return n-left;}
