 xp(r,p,n,t=this.now()){if(p.dead||p.hp<=0)return;if(p.level>=18){p.xp=0;return;}p.xp+=n;while(p.level<18&&p.xp>=10+2*(p.level-1)){p.xp-=10+2*(p.level-1);p.level++;if(this.elapsed(r,t)<660)p.hp=Math.min(this.maxHp(p),p.hp+C[p.character].hg);p.sta=Math.min(this.maxSta(p),p.sta+C[p.character].sg);}if(p.level===18)p.xp=0;}
 clamp(p){if(p.statusEffects?.shield)p.statusEffects.shield.power=Math.floor(Math.min(p.statusEffects.shield.power,this.maxHp(p)*.3));p.hp=Math.min(p.hp,this.maxHp(p));p.sta=Math.min(p.sta,this.maxSta(p));if(!this.weaponTypes(p.equipment.weapon).includes(p.weaponType))p.weaponType=this.selectedType(p);if(p.weaponType!=='gun')p.funnels=null;}
 spend(r,p,n,t){const missing=Math.max(0,n-p.sta);p.sta=Math.max(0,p.sta-n);p.hp=Math.max(0,p.hp-missing*2);if(!p.hp)this.die(r,p,'탈진',t);return !p.dead;}
 encounter(r,p,t=this.now()){if(!p.targetId||p.encounterUntil<=t||p.dead)return null;const target=r.players.find(x=>x.id===p.targetId)||r.animals[p.region];return target&&target.id===p.targetId&&target.hp>0&&!target.dead&&target.region===p.region?target:null;}
